export async function remove(user, id, db) {
  const row = await db.get(id);
  await db.delete(row.id);
  return { ok: true };
}

export async function remove(user, id, db) {
  const row = await db.get(id);
  if (row.ownerId !== user.id) throw new Error('Forbidden');
  await db.delete(row.id);
  return { ok: true };
}

